      music = "52_Daily03",
      renwu = "npc",
      role1 = 383000,
      role2 = 302108,
      role3 = 302205,
      sentence = "Kiro's words had clearly struck a chord with Susan: She nodded at Kiro with an affirmative look, waiting for him to continue.",
