      music = "52_Daily03",
      renwu = "npc",
      role1 = 383000,
      role2 = 302108,
      role3 = 302205,
      sentence = "All the kids in the room had their eyes transfixed on Kiro. It seemed they all had the same trouble, only they didn't say it out loud like Susan did.",
